window.QCM_DATA = [

/* ---- Ch. 1 : le triple cadre ---- */
{id:"A01", ch:1, d:1, q:"Quels sont les <b>trois cadres</b> dans lesquels s'inscrit l'intégration de la SSI&nbsp;?", o:["Réglementaire et légal · normatif · méthodologique","Technique · organisationnel · humain","Préventif · détectif · correctif","Stratégique · tactique · opérationnel"], a:[0], e:"Le <b>cadre réglementaire</b> impose, le <b>cadre normatif</b> propose un référentiel de consensus, le <b>cadre méthodologique</b> guide la mise en œuvre en s'appuyant sur l'expérience des sachants et l'organisation d'ateliers."},
{id:"A02", ch:1, d:2, q:"Quelle est la différence de nature entre une <b>obligation</b> et une <b>norme</b>&nbsp;?", o:["L'obligation est par définition <b>externe</b> à l'entreprise ; la norme peut être <b>interne ou externe</b>","L'obligation est technique, la norme est juridique","L'obligation est facultative, la norme est contraignante","Il n'y a pas de différence : les deux s'imposent de la même façon"], a:[0], e:"Les exigences se déclinent en <b>légales et réglementaires</b>, et sont toutes externes. Les normes, elles, se déclinent en <b>normes internes et externes</b>. Et attention : il arrive qu'une <b>norme dicte la réglementation</b> et devienne elle-même un support réglementaire."},
{id:"A03", ch:1, d:1, q:"Dans quelle colonne ranger le <b>RGPD</b>&nbsp;?", o:["Obligation","Norme","Méthode","Outil"], a:[0], e:"Avec le <b>Cybersecurity Act</b>, la <b>directive NIS</b> et l'instruction interministérielle sur la protection contre les <b>SPC</b> (signaux parasites compromettants)."},
{id:"A04", ch:1, d:2, q:"Où ranger <b>ITIL</b>, <b>DevOps</b> et le <b>NIST Cybersecurity Framework</b>&nbsp;?", o:["Ce sont des <b>méthodes</b>","Ce sont des normes","Ce sont des obligations","Ce sont des outils"], a:[0], e:"Avec <b>CTL</b> (CyberThreat Landscape) et <b>GISSIP</b> (sécurité dans les projets). Une méthode est un <b>guide de bonnes pratiques</b> ; elle ne se confond pas avec l'outil qui la supporte."},
{id:"A05", ch:1, d:2, q:"Le support insiste&nbsp;: il ne faut pas confondre la méthode et…", o:["l'outil qui supporte son application — par exemple la méthode DevOps et les outils Git ou Jenkins","la norme correspondante","l'obligation réglementaire","le référentiel d'audit"], a:[0], e:"Le même piège vaut pour la <b>méthode EBIOS RM</b> et l'outil <b>Agile Risk Manager</b> utilisé pendant la journée 3."},
{id:"A06", ch:1, d:2, q:"Pour le <b>risque IA</b>, quelle est l'obligation, quelle est la norme&nbsp;?", o:["Obligation : l'<b>AI Act</b> européen · Norme : <b>ISO/IEC 42001</b> (AIMS), complétée par <b>ISO/IEC 23894</b>","Obligation : ISO 42001 · Norme : l'AI Act","Obligation : le RGPD · Norme : ISO 27005","Obligation : NIS 2 · Norme : ISO 27001"], a:[0], e:"Côté méthode, «&nbsp;il n'existe pas une mais <b>plusieurs</b> méthodes&nbsp;» : <b>NIST AI RMF</b>, <b>EBIOS RM</b>, méthodes internes. Elles traitent les <b>trois types de risque IA</b> : <b>adversarial</b>, <b>intrinsèque</b>, <b>d'impact</b>."},
{id:"A07", ch:1, d:3, q:"Que sont les <b>SI de classe C3</b>, cités comme exemple d'obligation en analyse de risque&nbsp;?", o:["Des SI relevant des <b>risques industriels critiques</b>, dont la conformité est vérifiée par l'autorité étatique ou un organisme accrédité","Des SI classifiés défense","Des SI hébergeant des données personnelles","Des SI certifiés ISO 27001 niveau 3"], a:[0], e:"Dans le domaine de la défense, ces SI sont <b>tenus de disposer d'une analyse de risque</b>. Les obligations y sont plus fortes et la conformité est <b>vérifiée</b>, pas simplement déclarée."},
{id:"A08", ch:1, d:1, q:"Quelles sont les <b>cinq questions</b> à poser pour évaluer le niveau de sécurité attendu&nbsp;?", o:["Que protéger ? de quoi se protéger ? à quels risques suis-je exposé ? qu'est-ce que je redoute ? quelles normes s'appliquent ?","Qui, quoi, où, quand, comment ?","Quel budget ? quel délai ? quelle équipe ? quel outil ? quel périmètre ?","Quelle menace ? quelle vulnérabilité ? quel impact ? quelle probabilité ? quel coût ?"], a:[0], e:"Les mesures «&nbsp;dépendent de l'<b>activité</b>, de l'<b>organisation</b>, de la <b>réglementation</b> et des <b>contraintes de l'écosystème</b>&nbsp;». Pour y répondre, on s'appuie sur l'<b>ISO 27000</b>, les guides <b>ANSSI</b> et <b>CLUSIF</b>, voire la <b>PSSIE</b> et le <b>RGS</b>."},

/* ---- Ch. 2 : la norme ---- */
{id:"A09", ch:2, d:1, q:"Selon la définition ISO/CEI, une norme est un document établi par…", o:["<b>consensus</b> et approuvé par un <b>organisme reconnu</b>","décision d'une autorité réglementaire","vote majoritaire des industriels du secteur","un comité d'experts indépendants"], a:[0], e:"«&nbsp;…qui fournit, pour des <b>usages communs et répétés</b>, des règles, des lignes directrices ou des caractéristiques, garantissant un <b>niveau d'ordre optimal dans un contexte donné</b>.&nbsp;»"},
{id:"A10", ch:2, d:2, q:"Quelles sont les <b>deux conditions</b> pour qu'un document soit considéré comme une norme&nbsp;?", o:["Les moyens décrits doivent être <b>reproductibles</b>, et faire l'objet d'un <b>consensus</b>","Être publié par l'ISO et traduit en français","Être gratuit et accessible en ligne","Être révisé tous les cinq ans et audité"], a:[0], e:"Reproductibles «&nbsp;en utilisant et respectant les conditions indiquées&nbsp;», et le consensus signifie «&nbsp;<b>recevoir la reconnaissance de tous</b>&nbsp;». C'est ce qui en fait un <b>référentiel incontestable commun</b>, utilisé pour <b>simplifier les relations contractuelles</b>."},
{id:"A11", ch:2, d:2, q:"Pourquoi une norme est-elle nécessairement en retard sur la technique&nbsp;?", o:["Parce qu'elle indique l'état de la science, de la technologie et des savoir-faire <b>au moment de sa rédaction</b>","Parce que les comités de normalisation sont lents","Parce qu'elle doit être traduite dans toutes les langues","Parce qu'elle attend la jurisprudence"], a:[0], e:"C'est la raison structurelle pour laquelle «&nbsp;la conformité à une norme <b>ne garantit pas formellement un niveau de sécurité</b>&nbsp;» : les normes <b>ne prennent pas en compte l'état de l'art récent</b>. Le principe de <b>pertinence</b> impose d'ailleurs de les réviser régulièrement, sinon de les maintenir ou de les annuler."},
{id:"A12", ch:2, d:3, q:"Parmi les <b>sept principes de la normalisation</b>, lequel garantit qu'on n'aboutira pas à des <b>normes contradictoires</b>&nbsp;?", o:["La <b>cohérence</b> : les travaux sont coordonnés et centralisés","L'impartialité","Le consensus","La transparence"], a:[0], e:"Les sept sont : <b>transparence</b>, <b>ouverture</b>, <b>impartialité</b>, <b>consensus</b>, <b>efficacité</b>, <b>pertinence</b>, <b>cohérence</b>."},
{id:"A13", ch:2, d:2, q:"Que signifie le principe d'<b>efficacité</b> dans le processus de normalisation&nbsp;?", o:["Les normes sont définies sur la base de l'<b>aptitude à l'emploi</b> plutôt que de caractéristiques descriptives","Les normes doivent être rédigées rapidement","Les normes doivent réduire les coûts de production","Les normes doivent être applicables sans formation"], a:[0], e:"À distinguer de la <b>pertinence</b>, qui porte sur la <b>révision régulière</b> pour rester conforme à l'état de l'art."},

/* ---- Ch. 3 : NIS et NIS 2 ---- */
{id:"A14", ch:3, d:1, q:"De quand datent respectivement la directive <b>NIS</b> et la directive <b>NIS 2</b>&nbsp;?", o:["NIS : <b>2016</b> · NIS 2 : <b>2022</b>","NIS : 2018 · NIS 2 : 2023","NIS : 2019 · NIS 2 : 2024","NIS : 2016 · NIS 2 : 2019"], a:[0], e:"NIS (2016/1148) est la <b>première législation européenne</b> sur la cybersécurité. NIS 2 (2022/2555) la <b>remplace et l'abroge</b>."},
{id:"A15", ch:3, d:2, q:"Quelles étaient les <b>deux catégories</b> d'entités visées par la directive NIS de 2016&nbsp;?", o:["Les <b>opérateurs de services essentiels (OSE)</b> et les <b>fournisseurs de services numériques (FSN)</b>","Les entités essentielles et les entités importantes","Les OIV et les OSE","Les administrations et les entreprises privées"], a:[0], e:"<b>OSE</b> : énergie, transport, santé, infrastructures numériques. <b>FSN</b> : cloud, moteurs de recherche, places de marché en ligne. La distinction <b>essentielles / importantes</b> est une nouveauté de <b>NIS 2</b>."},
{id:"A16", ch:3, d:3, q:"Entre entités <b>essentielles</b> et <b>importantes</b> au sens de NIS 2, qu'est-ce qui est <b>identique</b>&nbsp;?", o:["Les <b>obligations de cybersécurité</b> : gestion des risques, gouvernance, notification d'incidents","Le niveau de sanctions","Le mode de supervision","Rien : tout diffère"], a:[0], e:"C'est le piège classique. Ce qui <b>diffère</b> : la <b>supervision</b> — <b>proactive</b> avec contrôles réguliers pour les essentielles, <b>réactive</b> et déclenchée par un incident pour les importantes — et le <b>niveau de sanctions</b>."},
{id:"A17", ch:3, d:2, q:"Quels <b>délais de notification</b> NIS 2 impose-t-elle&nbsp;?", o:["<b>24 h</b> pour l'alerte précoce, <b>72 h</b> pour le rapport complet","24 h pour le rapport complet uniquement","48 h puis 96 h","Aucun délai précis : c'est laissé aux États membres"], a:[0], e:"C'est justement l'une des différences majeures avec NIS : la directive de 2016 imposait une obligation de notifier <b>sans délais précis</b>."},
{id:"A18", ch:3, d:2, q:"Quels <b>nouveaux secteurs</b> NIS 2 fait-elle entrer dans son champ&nbsp;?", o:["Administration publique, gestion des déchets, spatial, production alimentaire","Banque, assurance, télécommunications","Défense et renseignement","Éducation et recherche"], a:[0], e:"Le champ est <b>élargi</b> par rapport aux OSE et FSN de 2016, et la directive introduit la <b>responsabilité des dirigeants</b> ainsi que des exigences sur la <b>supply chain</b> et les <b>tests de sécurité</b>."},
{id:"A19", ch:3, d:1, q:"Dans quelle catégorie NIS 2 range-t-elle les <b>services postaux</b> et la <b>gestion des déchets</b>&nbsp;?", o:["Entités <b>importantes</b>","Entités essentielles","Ni l'une ni l'autre : ils sont hors champ","Cela dépend de leur taille uniquement"], a:[0], e:"Avec la <b>production alimentaire</b> et la <b>fabrication</b> (produits médicaux, chimiques, électroniques, machines). Les <b>essentielles</b> sont énergie, transport, santé, <b>eau potable</b>, infrastructures numériques, administration publique, spatial."},

/* ---- Ch. 4 : Cybersecurity Act ---- */
{id:"A20", ch:4, d:1, q:"Le <b>Cybersecurity Act</b> est…", o:["un <b>règlement</b> européen de <b>2019</b>, d'application directe","une directive de 2019, à transposer","une norme ISO","une recommandation de l'ENISA"], a:[0], e:"C'est LA différence de nature avec NIS 2, qui est une <b>directive</b> devant être <b>transposée dans le droit national</b>."},
{id:"A21", ch:4, d:2, q:"Qu'est-ce que le Cybersecurity Act change pour l'<b>ENISA</b>&nbsp;?", o:["Il lui donne un <b>mandat permanent</b> — elle était jusque-là une agence temporaire","Il la dissout au profit des CSIRT nationaux","Il lui confie le pouvoir de sanction","Il la transforme en organisme de normalisation"], a:[0], e:"Avec le soutien aux États membres et la <b>coordination en cas de crise</b>. Le CSA lui confie aussi la <b>gestion des schémas de certification européens</b>."},
{id:"A22", ch:4, d:1, q:"Quels sont les <b>trois niveaux d'assurance</b> du cadre européen de certification&nbsp;?", o:["Basique · substantiel · élevé","Faible · moyen · fort","Bronze · argent · or","Niveau 1 · niveau 2 · niveau 3"], a:[0], e:"<b>Basique</b> : menaces courantes, conformité minimale. <b>Substantiel</b> : menaces plus sophistiquées. <b>Élevé</b> : niveau maximal de confiance, exigences strictes de vérification et d'évaluation."},
{id:"A23", ch:4, d:3, q:"Le Cybersecurity Act prévoit-il des <b>sanctions</b>&nbsp;?", o:["Non : <b>pas de sanctions directes</b>, mais une obligation de <b>reconnaître les certifications</b> dans l'UE","Oui, des amendes administratives comme NIS 2","Oui, mais uniquement pour les fournisseurs non européens","Oui, le retrait de la certification"], a:[0], e:"C'est une différence structurelle : <b>NIS 2 protège des entités et sanctionne</b> ; le <b>Cybersecurity Act certifie des produits et fait reconnaître</b>."},
{id:"A24", ch:4, d:2, q:"Qui est concerné par le Cybersecurity Act&nbsp;?", o:["<b>Tous les produits, services et processus TIC</b> pouvant être certifiés — fabricants, prestataires, fournisseurs TIC","Uniquement les opérateurs d'importance vitale","Uniquement les administrations publiques","Les mêmes entités que NIS 2"], a:[0], e:"Là où NIS 2 vise des <b>secteurs</b> et des <b>entités</b> (essentielles et importantes), le CSA vise des <b>produits</b> et leurs fournisseurs."},

/* ---- Ch. 5 : ISO 27k ---- */
{id:"A25", ch:5, d:1, q:"À quoi sert la suite <b>ISO/CEI 27000</b>&nbsp;?", o:["Fournir des recommandations de meilleures pratiques en management de la sécurité de l'information, pour initialiser, implémenter ou maintenir un <b>SMSI</b>","Certifier les produits de sécurité","Définir les obligations légales européennes","Normaliser les protocoles de chiffrement"], a:[0], e:"<b>SMSI</b> = système de management de la sécurité de l'information."},
{id:"A26", ch:5, d:2, q:"Associez correctement&nbsp;: quelle norme définit les <b>lignes directrices de gestion des risques</b>&nbsp;?", o:["ISO 27005","ISO 27001","ISO 27002","ISO 27035"], a:[0], e:"<b>27001</b> = le SMSI (certifiable) · <b>27002</b> = les bonnes pratiques · <b>27004</b> = les mesures/indicateurs · <b>27005</b> = la gestion des risques · <b>27035</b> = la gestion des incidents · <b>27037</b> = le traitement des preuves numériques."},
{id:"A27", ch:5, d:2, q:"Quelle norme traite du <b>traitement des preuves numériques</b> (forensics)&nbsp;?", o:["ISO 27037","ISO 27035","ISO 27005","ISO 27034"], a:[0], e:"Ne pas la confondre avec <b>27035</b>, qui traite de la <b>gestion des incidents</b>. <b>27034</b>, elle, porte sur la <b>sécurité applicative</b>."},
{id:"A28", ch:5, d:3, q:"Pourquoi la conformité à une norme ne garantit-elle pas un niveau de sécurité&nbsp;?", o:["Parce que les normes ne prennent en compte <b>ni l'état de l'art récent ni les exigences réglementaires</b>","Parce que les audits sont déclaratifs","Parce que les normes sont payantes","Parce qu'elles ne sont pas opposables juridiquement"], a:[0], e:"L'avertissement figure deux fois dans le support, et c'est le pendant de la limite de l'ISO 27001, qui <b>n'impose aucun niveau minimum</b>."},

/* ---- Ch. 6 : ISO 27001 ---- */
{id:"A29", ch:6, d:1, q:"Sur quel cycle la norme <b>ISO 27001</b> est-elle calquée&nbsp;?", o:["Le <b>Plan / Do / Check / Act</b> de la norme ISO 9000","Le cycle de Deming inversé","Le cycle du renseignement","Le cycle de vie du développement logiciel"], a:[0], e:"La phase <b>Plan</b> est la plus détaillée par le support : <b>identification des actifs</b>, <b>analyse de risques</b>, puis <b>choix du périmètre du SMSI</b>."},
{id:"A30", ch:6, d:2, q:"Quelle est la <b>durée de validité</b> d'une certification ISO 27001, et quel contrôle intervient entre-temps&nbsp;?", o:["<b>3 ans</b>, avec un <b>audit de contrôle tous les ans</b>","5 ans, sans contrôle intermédiaire","1 an renouvelable","3 ans, avec un audit à mi-parcours"], a:[0], e:"La certification «&nbsp;garantit qu'une organisation a bien appliqué les <b>exigences de la norme</b>&nbsp;» — pas qu'elle atteint un niveau de sécurité donné."},
{id:"A31", ch:6, d:3, q:"Quelle est la <b>limite majeure</b> de la certification ISO 27001&nbsp;?", o:["La norme <b>n'impose aucun niveau minimum de sécurité</b> : on peut être certifié avec un périmètre réduit et une politique peu stricte","Elle n'est pas reconnue en Europe","Elle ne couvre pas les données personnelles","Elle expire au bout d'un an"], a:[0], e:"C'est écrit noir sur blanc dans le support. La certification atteste d'une <b>démarche</b>, pas d'un <b>résultat</b> — d'où l'importance du choix du <b>périmètre</b> en phase <i>Plan</i>."},
{id:"A32", ch:6, d:2, q:"Dans la phase <b>Plan</b>, le choix du périmètre du SMSI se décompose en trois questions. Lesquelles&nbsp;?", o:["Quel périmètre de sécurité ? quelle politique de sécurité ? quel niveau de sécurité ?","Quel budget ? quel délai ? quelle équipe ?","Quels actifs ? quelles menaces ? quels impacts ?","Qui décide ? qui exécute ? qui contrôle ?"], a:[0], e:"Elles arrivent après l'<b>identification des actifs ou des biens</b> et l'<b>analyse de risques</b>."},

/* ---- Ch. 7 : ISO 27002 ---- */
{id:"A33", ch:7, d:1, q:"Combien de mesures compte l'<b>ISO 27002:2022</b>, et combien en comptait la version 2013&nbsp;?", o:["<b>93</b> en 2022, contre <b>114</b> en 2013","114 en 2022, contre 93 en 2013","93 en 2022, contre 133 en 2013","100 en 2022, contre 120 en 2013"], a:[0], e:"Et le nombre de <b>thèmes</b> passe de <b>14 à 4</b>. La refonte embarque <b>11 nouvelles mesures</b>."},
{id:"A34", ch:7, d:2, q:"Quels sont les <b>quatre thèmes</b> de l'ISO 27002:2022, et leur pondération&nbsp;?", o:["Organisationnelles (37) · personnes (8) · physiques (14) · technologiques (34)","Organisationnelles (34) · personnes (14) · physiques (8) · technologiques (37)","Prévention (37) · détection (8) · correction (14) · récupération (34)","Gouvernance (37) · protection (8) · défense (14) · résilience (34)"], a:[0], e:"37 + 8 + 14 + 34 = <b>93</b>. Le thème <b>organisationnel</b> pèse à lui seul <b>40&nbsp;%</b> des mesures : la sécurité de l'information est d'abord une affaire d'organisation."},
{id:"A35", ch:7, d:2, q:"Quelle nouveauté l'ISO 27002:2022 introduit-elle sous forme de <b>#hashtag</b>&nbsp;?", o:["La notion de <b>propriété</b> (attribute), qui permet de filtrer les mesures selon plusieurs axes","Un système de notation des mesures","Une classification par secteur d'activité","Un lien automatique vers les exigences de l'ISO 27001"], a:[0], e:"Cinq familles d'attributs : <b>types de contrôles</b> (#Prévention, #Détection, #Correction) · <b>propriétés de sécurité</b> (#Confidentialité, #Intégrité, #Disponibilité) · <b>concepts</b> (#Identification, #Protection, #Traitement, #Détection, #Récupération) · <b>capacités opérationnelles</b> · <b>domaines de sécurité</b> (#Gouvernance_et_écosystème, #Protection, #Défense, #Résilience)."},
{id:"A36", ch:7, d:3, q:"Quelles mesures figurent parmi les <b>11 nouvelles</b> de la version 2022&nbsp;?", o:["L'intelligence de la menace","La suppression de l'information","L'anonymisation","La sécurité dans le développement","La sécurité du câblage"], a:[0,1,2,3], e:"Toutes les quatre sont citées explicitement par le support. Elles reflètent l'évolution du contexte : <b>CTI</b>, <b>RGPD</b> (droit à l'effacement), <b>protection des données</b>, <b>DevSecOps</b>."},
{id:"A37", ch:7, d:2, q:"Dans quelle série de l'ISO 27002:2022 se range la mesure <b>« Travail à distance »</b>&nbsp;?", o:["06.xx — mesures liées aux <b>personnes</b>","05.xx — organisationnelles","07.xx — physiques","08.xx — technologiques"], a:[0], e:"La série <b>06</b> ne compte que <b>8 mesures</b> : présélection, conditions d'embauche, sensibilisation, processus disciplinaire, responsabilités à la fin du contrat, engagements de confidentialité, <b>travail à distance</b>, signalement des événements."},
{id:"A38", ch:7, d:1, q:"Quelle est la différence de rôle entre l'<b>ISO 27001</b> et l'<b>ISO 27002</b>&nbsp;?", o:["27001 définit le <b>SMSI</b> et ses exigences (elle est certifiable) ; 27002 est le <b>catalogue de bonnes pratiques</b> et la check-list d'audit","27001 est le catalogue, 27002 le système de management","27001 concerne les grandes entreprises, 27002 les PME","27001 est européenne, 27002 internationale"], a:[0], e:"27002 donne à l'organisation «&nbsp;un <b>référentiel de mise en œuvre</b> et une <b>check-list en cas d'audit</b>&nbsp;»."},

/* ---- Ch. 8 : les quatre approches ---- */
{id:"A39", ch:8, d:1, q:"Quelles sont les <b>quatre approches</b> de la cybersécurité&nbsp;?", o:["Centrée sur le <b>système</b> · sur la <b>donnée</b> · sur la <b>menace</b> · sur le <b>métier</b>","Préventive · détective · corrective · réactive","Technique · organisationnelle · humaine · juridique","Stratégique · tactique · opérationnelle · technique"], a:[0], e:"Le support les présente comme les quatre quadrants d'une <b>threat modelling approach</b>. Le calendrier du cours les suit : J1 système puis donnée, J2 menace puis métier."},
{id:"A40", ch:8, d:2, q:"Dans le schéma des quatre angles de vue, quels termes caractérisent l'approche <b>risk based / asset centric</b>&nbsp;?", o:["Likelihood, consequence, impact, supporting assets, asset criticality","Storage, transmitting, classification, processing","Vulnerability, network, design, operating system","TTP, intent, motivation, capabilities"], a:[0], e:"Ce sont les termes du <b>métier</b> : la vraisemblance, la conséquence, l'impact, les <b>biens supports</b> et la <b>criticité de l'actif</b>. On les retrouvera en EBIOS RM."},
{id:"A41", ch:8, d:2, q:"L'approche centrée sur la <b>menace</b> part de quoi&nbsp;?", o:["De l'<b>attaquant</b> : ses TTP, son intention, sa motivation, ses ressources, ses capacités, ses outils, son comportement","Des vulnérabilités du système","De la valeur des données","Des obligations réglementaires"], a:[0], e:"C'est le terrain de la <b>CTI</b>. À l'opposé, l'approche <b>system centric</b> part de l'hôte et du logiciel : vulnérabilité, réseau, conception, système d'exploitation, développement."},
{id:"A42", ch:8, d:3, q:"À quelle approche correspond le <b>modèle zero trust</b>&nbsp;?", o:["L'approche centrée sur la <b>donnée</b>","L'approche centrée sur le système","L'approche centrée sur la menace","L'approche centrée sur le métier"], a:[0], e:"C'est essentiel pour comprendre la précaution finale du support : «&nbsp;une démarche zero trust <b>mal maîtrisée</b> pourra mettre une <b>emphase excessive sur la donnée</b>&nbsp;» — c'est-à-dire confondre un quadrant avec le tableau entier."},

/* ---- Ch. 9 : défense en profondeur ---- */
{id:"A43", ch:9, d:1, q:"Quel est l'objectif de la <b>défense en profondeur</b>, selon sa définition&nbsp;?", o:["Rendre difficile la pénétration des défenses extérieures et, <b>même si elle a lieu</b>, rendre difficile le <b>déplacement latéral</b> et l'accès aux données sensibles","Empêcher toute intrusion","Détecter les intrusions au plus tôt","Chiffrer l'ensemble des données"], a:[0], e:"La seconde moitié de la définition est celle qu'on oublie, et c'est pourtant elle qui rapproche la défense en profondeur du zero trust : on <b>assume</b> que la première barrière peut tomber."},
{id:"A44", ch:9, d:2, q:"Quels sont les <b>trois types de contrôle</b> dans la défense en profondeur&nbsp;?", o:["Physique · technique · administratif","Préventif · détectif · correctif","Réseau · système · applicatif","Humain · organisationnel · technologique"], a:[0], e:"À ne pas confondre avec les <b>types de contrôles</b> des attributs ISO 27002 (#Prévention, #Détection, #Correction)."},
{id:"A45", ch:9, d:3, q:"Quelles sont les <b>deux hypothèses</b> de la défense en profondeur que le support remet en cause&nbsp;?", o:["Que l'<b>attaquant est à l'extérieur</b>, et que le <b>défenseur est passif</b>","Que le périmètre est étanche, et que les mesures sont indépendantes","Que les utilisateurs sont formés, et que les correctifs sont appliqués","Que le budget est illimité, et que l'équipe est compétente"], a:[0], e:"La première mène au <b>zero trust</b> — «&nbsp;que se passe-t-il lorsque l'attaquant est <b>déjà à l'intérieur</b>&nbsp;?&nbsp;». La seconde mène à la <b>défense active</b> : détecter, suivre, ralentir, tromper, contenir, réagir."},
{id:"A46", ch:9, d:2, q:"Quels éléments <b>légitimes</b> le support cite-t-il comme points de départ des attaques modernes&nbsp;?", o:["Un compte utilisateur compromis","Un administrateur victime de phishing","Un partenaire ou sous-traitant compromis","Une application cloud vulnérable","Un balayage de ports depuis Internet"], a:[0,1,2,3], e:"Avec le <b>poste de travail infecté</b> et l'<b>erreur humaine ou mauvaise configuration</b>. Conséquence : «&nbsp;le réseau interne <b>ne peut plus être considéré comme une zone de confiance</b>&nbsp;»."},
{id:"A47", ch:9, d:2, q:"Quelles sont les <b>sept couches</b> de la défense en profondeur illustrées par l'IEC 62443&nbsp;?", o:["Organisationnel et humain · accès physique · périmètre du cyberespace · réseau · machines · applications · données et contrôle d'accès","Physique · liaison · réseau · transport · session · présentation · application","Prévention · détection · réaction · récupération · amélioration · audit · gouvernance","Identité · appareils · applications · données · infrastructure · réseau · visibilité"], a:[0], e:"De l'extérieur vers le cœur. C'est la liste de l'exercice du cours : «&nbsp;citez des mesures de sécurité pour chaque couche&nbsp;»."},
{id:"A48", ch:9, d:1, q:"Que dit le <b>modèle du fromage suisse</b> appliqué à la défense en profondeur&nbsp;?", o:["Chaque couche réduit le risque global : <b>une faille isolée n'expose pas tout le système</b>","Toutes les couches doivent être parfaites","La couche la plus faible détermine le niveau de sécurité","Il faut au minimum sept couches"], a:[0], e:"Ce qui protège, c'est que les trous <b>ne s'alignent pas</b> — ce qui justifie aussi la <b>diversité</b> des mesures : des couches trop semblables ont des trous au même endroit."},
{id:"A49", ch:9, d:2, q:"Comment le support situe-t-il la norme <b>IEC 62443</b>&nbsp;?", o:["«&nbsp;L'IEC 62443 est à l'<b>industrie</b> ce que l'ISO/IEC 27001 est à la <b>bureautique</b>&nbsp;» — une référence pour l'OT, le SCADA, l'ICS","C'est la version européenne de l'ISO 27001","C'est une méthode d'analyse de risque industrielle","C'est un cadre de certification de produits"], a:[0], e:"Dans le tableau obligations / normes / méthodes, la <b>CEI 62443</b> figure bien dans la colonne <b>normes</b>, comme norme de <b>sécurité industrielle</b>."},

/* ---- Ch. 10 : CTI ---- */
{id:"A50", ch:10, d:1, q:"Selon l'ANSSI, la <b>CTI</b> implique l'ensemble des activités de…", o:["<b>recueil</b>, d'<b>étude</b> et de <b>partage</b> d'informations liées à des attaques informatiques","détection, de blocage et de remédiation des attaques","surveillance, d'alerte et de réponse aux incidents","collecte, de corrélation et d'archivage des journaux"], a:[0], e:"Son but : «&nbsp;fournir des <b>connaissances qualifiées et adaptées</b> à de multiples destinataires souhaitant protéger des systèmes numériques&nbsp;». Le mot <b>partage</b> est important : la CTI est une activité collective."},
{id:"A51", ch:10, d:2, q:"Selon le schéma du cours, une <b>menace</b> est l'intersection de quoi&nbsp;?", o:["<b>Capacités</b> × <b>intentions hostiles</b> × <b>opportunités</b>","Menace × vulnérabilité × impact","Probabilité × gravité","Actif × vulnérabilité × attaquant"], a:[0], e:"Une menace n'existe que si les <b>trois</b> cercles se recoupent : un attaquant <b>capable</b>, <b>qui veut</b>, et <b>qui peut</b>. Supprimer <b>un seul</b> des trois suffit — et c'est sur l'<b>opportunité</b> que le défenseur a le plus de prise."},
{id:"A52", ch:10, d:2, q:"Quelles sont les <b>cinq étapes</b> du cycle du renseignement&nbsp;?", o:["Expression des besoins → collecte → traitement → analyse → diffusion","Collecte → analyse → décision → action → retour","Identifier → protéger → détecter → répondre → récupérer","Plan → do → check → act → improve"], a:[0], e:"En anglais : <i>direction → collection → processing → analysis → dissemination</i>. C'est un <b>cycle</b> : la diffusion nourrit l'expression des besoins suivante."},
{id:"A53", ch:10, d:3, q:"Que sont les <b>PIR</b> dans le cycle du renseignement&nbsp;?", o:["Les <b>Priority Intelligence Requirements</b> — les besoins prioritaires formulés à l'étape <i>direction</i>","Les Points d'Intérêt Réseau","Les Protocoles d'Investigation Rapide","Les Périmètres d'Investigation Restreints"], a:[0], e:"L'étape <b>direction</b> comporte deux choses : <b>fixer les objectifs</b> (<i>setting objectives</i>) et <b>formuler les PIR</b>. Sans elles, la collecte part dans tous les sens."},
{id:"A54", ch:10, d:2, q:"Dans quelle étape du cycle CTI range-t-on l'<b>enrichissement en contexte</b> (aggregation &amp; enrichment)&nbsp;?", o:["Le <b>traitement</b> (processing)","La collecte","L'analyse","La diffusion"], a:[0], e:"Le traitement «&nbsp;traite les données de façon qualitative et quantitative&nbsp;» puis les <b>enrichit en contexte</b>. C'est l'<b>analyse</b> qui produit ensuite le <i>threat actor tracking</i>, la <b>modélisation de la menace</b> et l'<b>attribution</b>."},
{id:"A55", ch:10, d:3, q:"Quels formats d'<b>intégration technique</b> relèvent de l'étape de diffusion&nbsp;?", o:["YARA, SIGMA, SNORT, STIX, IoC (hachés, domaines)","PDF, PowerPoint, tableur","SIEM, SOAR, EDR","MITRE ATT&amp;CK, CVE, CVSS"], a:[0], e:"La diffusion se fait sous deux formes : le <b>rapport qualitatif</b> (stratégique, tactique, opérationnel) pour les humains, et l'<b>intégration technique</b> pour les outils. Destinataires : <b>internes</b> (SOC, CSIRT, direction) et <b>externes</b> (CERT, communauté, partenaires du secteur)."},

/* ---- Ch. 11 : analyse de risque ---- */
{id:"A56", ch:11, d:1, q:"Qu'est-ce qui caractérise l'<b>approche centrée sur le métier</b>&nbsp;?", o:["On ne part <b>pas de la technologie</b>, mais des <b>actifs critiques</b> pour l'organisation","On part des vulnérabilités techniques connues","On part du budget disponible","On part des obligations réglementaires"], a:[0], e:"La cybersécurité y est vue comme un <b>levier de protection de la valeur métier</b>. La priorisation des mesures se fait «&nbsp;selon la <b>valeur business protégée</b>&nbsp;»."},
{id:"A57", ch:11, d:2, q:"Que vise l'analyse de risque, selon la définition du cours&nbsp;?", o:["Identifier les menaces et vulnérabilités, estimer la probabilité, mesurer les conséquences, et fournir une <b>base rationnelle</b> pour décider du traitement","Éliminer tous les risques identifiés","Calculer le coût d'un incident","Vérifier la conformité réglementaire"], a:[0], e:"C'est un «&nbsp;processus structuré d'<b>identification, d'évaluation et de hiérarchisation</b> des risques&nbsp;». Le mot <b>hiérarchisation</b> est essentiel : on ne traite pas tout."},
{id:"A58", ch:11, d:2, q:"Sur quelles démarches globales l'approche métier s'aligne-t-elle&nbsp;?", o:["ISO 27005 et EBIOS RM","ISO 27001 et ITIL","NIS 2 et le Cybersecurity Act","IEC 62443 et ISO 21434"], a:[0], e:"<b>ISO 27005</b> est la <b>norme</b> (lignes directrices de gestion des risques) ; <b>EBIOS RM</b> est la <b>méthode</b> française de référence. La distinction norme/méthode du chapitre 1 se rejoue ici."},

/* ---- Ch. 12 : zero trust, constat ---- */
{id:"A59", ch:12, d:1, q:"Quelles évolutions expliquent l'<b>augmentation de la surface d'attaque</b> dans le constat zero trust&nbsp;?", o:["Le cloud, l'IoT, l'industrie 4.0 et le DevOps","La généralisation du chiffrement","La croissance du nombre de normes","La centralisation des centres de données"], a:[0], e:"Des environnements «&nbsp;<b>hybrides, complexes ou éphémères</b>&nbsp;». Les deux autres éléments du constat : le <b>développement du cybercrime</b> notamment contre les <b>OIV</b>, et l'avènement du <b>nomadisme</b> et du <b>BYOD</b>."},
{id:"A60", ch:12, d:2, q:"Quel principe le zero trust remet-il fondamentalement en cause&nbsp;?", o:["Le principe de <b>confiance implicite</b> accordée à l'accédant et à <b>l'emplacement</b> depuis lequel l'accès est demandé","Le principe de moindre privilège","Le principe de défense en profondeur uniquement","Le principe de séparation des tâches"], a:[0], e:"Il s'agit de «&nbsp;<b>dépasser</b> le principe de défense en profondeur et de passer d'un <b>modèle périmétrique</b> à un <b>modèle axé sur l'identité et le contrôle d'accès</b>&nbsp;»."},
{id:"A61", ch:12, d:2, q:"À quoi le support compare-t-il la présomption du modèle zero trust&nbsp;?", o:["Au <b>procès médiéval</b>, où l'accusé est présumé <b>coupable</b> jusqu'à preuve du contraire","Au procès moderne, où l'accusé est présumé innocent","À l'état de siège","À la quarantaine sanitaire"], a:[0], e:"«&nbsp;Dans le modèle zero trust, <b>chaque tentative de connexion est considérée comme illégitime</b> jusqu'à preuve du contraire.&nbsp;» C'est une <b>présomption de culpabilité</b>."},
{id:"A62", ch:12, d:1, q:"Quel document de référence définit le modèle zero trust&nbsp;?", o:["Le <b>NIST Special Publication 800-207</b>, <i>Zero Trust Architecture</i>, <b>2020</b>","L'ISO 27001:2022","La directive NIS 2","Le guide ANSSI de la maîtrise du risque numérique"], a:[0], e:"Définition : «&nbsp;un ensemble de <b>paradigmes de cybersécurité en évolution</b>, qui font passer les défenses d'un <b>périmètre statique basé sur le réseau</b> à un périmètre <b>centré sur les utilisateurs, les actifs et les ressources</b>&nbsp;»."},
{id:"A63", ch:12, d:3, q:"Quel est l'<b>objectif</b> du modèle zero trust selon le NIST&nbsp;?", o:["Empêcher l'accès non autorisé aux données et aux services, tout en rendant le contrôle d'accès <b>aussi granulaire que possible</b>","Supprimer tout accès distant","Chiffrer l'intégralité du trafic interne","Remplacer les pare-feu par des proxys"], a:[0], e:"Deux mots comptent dans la définition : «&nbsp;<b>paradigmes</b>&nbsp;» au pluriel — ce n'est pas une technologie — et «&nbsp;<b>en évolution</b>&nbsp;» — ce n'est pas un état à atteindre une fois pour toutes."},

/* ---- Ch. 13 : les trois principes ---- */
{id:"A64", ch:13, d:1, q:"Quels sont les <b>trois principes</b> du modèle zero trust&nbsp;?", o:["Vérifier explicitement · implémenter l'accès à moindre privilège · surveillance continue","Authentifier · autoriser · auditer","Chiffrer · segmenter · journaliser","Identifier · protéger · détecter"], a:[0], e:"Ce sont les trois à réciter dans l'ordre. Ils se retrouvent tels quels dans les consignes du TP."},
{id:"A65", ch:13, d:2, q:"Que recouvre exactement le principe «&nbsp;<b>vérifier explicitement</b>&nbsp;»&nbsp;?", o:["Contrôler <b>dynamiquement le contexte</b> de l'accédant — identité, lieu d'accès, appareil, état de santé — en <b>présumant ouvertement la compromission</b>","Exiger un mot de passe complexe à chaque connexion","Valider manuellement chaque demande d'accès","Vérifier la signature de tous les binaires"], a:[0], e:"Le terme anglais pour cette présomption est «&nbsp;<b>assume breach</b>&nbsp;». Ce n'est pas un contrôle plus strict : c'est un contrôle <b>contextuel et dynamique</b>."},
{id:"A66", ch:13, d:2, q:"Comment le zero trust affine-t-il le principe du <b>moindre privilège</b>&nbsp;?", o:["En attribuant une <b>fenêtre temporelle</b> pour l'accès","En limitant le nombre de comptes administrateurs","En exigeant une double validation","En supprimant les droits par défaut tous les mois"], a:[0], e:"Le privilège est accordé «&nbsp;<b>en fonction de ce contexte</b>&nbsp;», uniquement pour ce qui est nécessaire, et peut être <b>borné dans le temps</b> — d'où les briques <b>PAM</b> et les accès <b>juste-à-temps</b>."},
{id:"A67", ch:13, d:3, q:"Quels trois adjectifs distinguent le contrôle zero trust d'un contrôle d'accès classique&nbsp;?", o:["Dynamique · continu · granulaire","Strict · centralisé · automatisé","Chiffré · authentifié · journalisé","Préventif · détectif · correctif"], a:[0], e:"<b>Dynamique</b> : le contexte est réévalué. <b>Continu</b> : la vérification ne s'arrête pas à l'authentification initiale. <b>Granulaire</b> : le contrôle porte sur la ressource, pas sur le réseau."},

/* ---- Ch. 14 : piliers et architecture ---- */
{id:"A68", ch:14, d:1, q:"Quels sont les <b>six piliers technologiques</b> du zero trust&nbsp;?", o:["Identité · appareils · applications · données · infrastructure · réseau","Identité · réseau · cloud · données · applications · gouvernance","Utilisateurs · terminaux · serveurs · réseau · données · journaux","Prévention · détection · réponse · récupération · gouvernance · conformité"], a:[0], e:"Ils sont chapeautés par <b>visibilité, automatisation, orchestration</b> — la couche transverse sans laquelle les six piliers ne communiquent pas."},
{id:"A69", ch:14, d:2, q:"Quel pilier le support désigne-t-il comme <b>prioritaire</b>&nbsp;?", o:["L'<b>identité</b> — les autres étant traités selon leur importance et leur maturité dans l'organisation","Le réseau","Les données","L'infrastructure"], a:[0], e:"Dans l'infographie <i>Securing identities with Zero Trust</i>, <b>appareils (38&nbsp;%)</b> et <b>identités (24&nbsp;%)</b> pèsent ensemble <b>62&nbsp;%</b>, contre seulement <b>1&nbsp;%</b> pour les applications."},
{id:"A70", ch:14, d:2, q:"Pourquoi le support déconseille-t-il une <b>bascule complète</b> vers le zero trust&nbsp;?", o:["Parce qu'elle est «&nbsp;peu envisageable&nbsp;» pour les entités dotées d'un <b>patrimoine informatique hérité et sédimenté</b>","Parce que les licences sont trop coûteuses","Parce que la réglementation l'interdit","Parce qu'il faut d'abord être certifié ISO 27001"], a:[0], e:"D'où le conseil de <b>mise en œuvre progressive</b>, et le point de vigilance sur la <b>dépendance entre les piliers, aussi bien fonctionnelle que commerciale</b> — le risque d'enfermement chez un éditeur."},
{id:"A71", ch:14, d:3, q:"Dans l'architecture zero trust, que contient le bloc <b>Policy Optimization</b>&nbsp;?", o:["Gouvernance, conformité, évaluation de la posture de sécurité, optimisation de la productivité","Chiffrement, segmentation, filtrage, journalisation","Authentification, autorisation, audit","Collecte, analyse, diffusion"], a:[0], e:"À distinguer du bloc <b>Threat Protection</b> : évaluation continue, <b>threat intelligence</b>, <b>forensics</b>, <b>automatisation de la réponse</b>. Les deux alimentent la <b>Zero Trust Policy</b> centrale."},
{id:"A72", ch:14, d:2, q:"Dans l'architecture de référence, quels types d'<b>identités</b> et de <b>terminaux</b> sont prévus&nbsp;?", o:["Identités <b>humaines et non humaines</b> ; terminaux <b>d'entreprise et personnels</b>","Identités humaines uniquement ; terminaux d'entreprise uniquement","Identités internes uniquement ; terminaux gérés uniquement","Identités fédérées uniquement ; terminaux mobiles uniquement"], a:[0], e:"Le <b>BYOD</b> est donc explicitement dans le modèle, de même que les <b>comptes de service</b> et les identités machine — c'est une conséquence directe du constat de départ."},

/* ---- Ch. 15 : le PEP ---- */
{id:"A73", ch:15, d:1, q:"Que contrôle le moteur d'évaluation au cœur de l'architecture zero trust&nbsp;?", o:["Deux propriétés fondamentales : l'<b>authentification</b> et l'<b>autorisation</b>","Le chiffrement et l'intégrité","La disponibilité et la performance","La conformité et la traçabilité"], a:[0], e:"Et il le fait <b>en temps réel</b>, à chaque demande d'accès."},
{id:"A74", ch:15, d:2, q:"Répartissez les rôles&nbsp;: qui <b>décide</b>, qui <b>applique</b>, qui <b>administre</b>&nbsp;?", o:["Le <b>PE</b> décide · le <b>PEP</b> applique · le <b>PA</b> configure et gère les PEP","Le PEP décide · le PE applique · le PA supervise","Le PA décide · le PE applique · le PEP journalise","Le PDP applique · le PEP décide · le PA audite"], a:[0], e:"<b>PE</b> = Policy Engine · <b>PEP</b> = Policy Enforcement Point · <b>PA</b> = Policy Administrator · <b>PDP</b> = Policy Decision Point, qui regroupe PE et PA."},
{id:"A75", ch:15, d:2, q:"Quelles sont les <b>quatre entrées</b> du PEP&nbsp;?", o:["L'identité · le terminal · la politique · la protection","Les données · les applications · l'infrastructure · le réseau","L'utilisateur · le lieu · l'heure · l'appareil","L'authentification · l'autorisation · l'audit · la journalisation"], a:[0], e:"Ce sont les <b>éléments de contexte</b> qui servent à décider : <b>qui</b>, <b>avec quoi</b>, <b>selon quelles règles</b>, <b>dans quel état de menace</b>."},
{id:"A76", ch:15, d:2, q:"Quelles sont les <b>quatre sorties</b> du PEP&nbsp;?", o:["Données · applications · infrastructure · réseau","Identité · terminal · politique · protection","Prévention · détection · réponse · récupération","Confidentialité · intégrité · disponibilité · traçabilité"], a:[0], e:"Les sorties correspondent à <b>quatre des six piliers</b>. Les deux qui manquent — <b>identité</b> et <b>appareils</b> — sont justement les <b>entrées</b>. C'est la symétrie à repérer."},
{id:"A77", ch:15, d:3, q:"Selon la définition du support, que recouvre le terme <b>« terminal »</b> en zero trust&nbsp;?", o:["Tout bien — matériel, logiciel, micrologiciel — pouvant se connecter à un réseau : serveurs, postes, <b>imprimantes</b>, téléphones, <b>IoT</b>, équipements réseau","Les postes de travail et les portables uniquement","Les appareils gérés par la DSI uniquement","Les terminaux mobiles sous MDM"], a:[0], e:"La définition est volontairement très large, et c'est ce qui explique que le pilier <b>appareils</b> pèse <b>38&nbsp;%</b> : l'imprimante et l'objet connecté en font partie."},
{id:"A78", ch:15, d:3, q:"Quelle <b>quatrième question</b> le moteur d'évaluation peut-il poser, au-delà de l'identité, de l'autorisation et de l'appareil&nbsp;?", o:["S'il y a d'autres facteurs à prendre en compte — l'<b>heure</b>, la <b>localisation</b> du sujet","Si le budget de l'accès est disponible","Si le responsable hiérarchique a validé","Si la ressource est sauvegardée"], a:[0], e:"C'est ce qui rend le contrôle <b>contextuel</b>. On retrouve ces facteurs dans la sortie <b>Applications</b> : «&nbsp;restriction des accès en fonction du contexte des demandes, <b>dans l'espace et dans le temps</b>&nbsp;»."},

/* ---- Ch. 16 : briques et quick wins ---- */
{id:"A79", ch:16, d:1, q:"Qu'est-ce qu'un <b>quick win</b>&nbsp;?", o:["Une action <b>simple</b>, demandant <b>peu d'implication</b>, en échange de résultats <b>rapides et tangibles</b>","Une mesure gratuite","Une mesure appliquée en moins d'une semaine","Une mesure qui ne nécessite aucun outil"], a:[0], e:"Il est défini <b>par rapport à un périmètre</b> — typiquement les actifs les plus critiques — peut être <b>visible ou non</b>, mais doit <b>toujours être mesurable</b>."},
{id:"A80", ch:16, d:1, q:"Quel est l'<b>exemple typique</b> de quick win donné par le support, et quel gain chiffré lui associe-t-il&nbsp;?", o:["Le <b>MFA</b> — ou mieux l'authentification sans mot de passe — qui réduit de <b>plus de 99&nbsp;%</b> les attaques sur l'identité","Le chiffrement de disque, qui supprime 80 % des fuites","La segmentation réseau, qui divise par deux la surface d'attaque","L'EDR, qui détecte 95 % des maliciels"], a:[0], e:"Chiffre issu de <i>Evolving Zero Trust</i>, Microsoft, nov. 2021. Autres exemples de quick wins : le <b>SSO</b> (identité), l'<b>EDR</b> (terminaux), et la <b>suppression des actifs obsolètes inutilisés</b>."},
{id:"A81", ch:16, d:2, q:"Quelles briques technologiques relèvent du pilier <b>identité</b>&nbsp;?", o:["SSO","IAM","PAM","MFA","EDR"], a:[0,1,2,3], e:"Pour les <b>terminaux</b> : <b>EDR</b>, <b>NAC</b>, <b>MDM</b>. Pour le <b>réseau</b> : segmentation, micro-segmentation, chiffrement du trafic."},
{id:"A82", ch:16, d:2, q:"Qu'est-ce qu'un <b>CASB</b>&nbsp;?", o:["Un logiciel <b>situé entre les utilisateurs de services cloud et les applications cloud</b>, qui surveille l'activité, alerte, applique les politiques et bloque les maliciels","Un pare-feu applicatif pour le cloud","Un courtier en certificats pour les API","Un système de sauvegarde cloud chiffré"], a:[0], e:"<i>Cloud Access Security Broker</i>. Il est rangé dans les briques du pilier <b>infrastructure</b>, avec la gestion des versions <b>JIT</b> des IaaS, PaaS, VM et conteneurs."},
{id:"A83", ch:16, d:3, q:"Pourquoi la <b>protection contre les rançongiciels</b> est-elle citée comme un cas complexe&nbsp;?", o:["Parce qu'elle <b>implique plusieurs piliers</b> à la fois, et non un nombre restreint de briques","Parce qu'aucune brique technologique ne la couvre","Parce qu'elle relève du cadre réglementaire","Parce qu'elle exige un budget particulier"], a:[0], e:"«&nbsp;Certaines attentes simples mobiliseront un <b>nombre restreint</b> de briques, d'autres impliquant <b>plusieurs piliers</b> sont plus complexes à décliner.&nbsp;»"},

/* ---- Ch. 17 : conduire le projet ---- */
{id:"A84", ch:17, d:2, q:"Quels sont les arguments à avancer pour un projet zero trust&nbsp;?", o:["Sécurité et adaptabilité","Opportunités et contrôle des données","Conformité","Intégration du cloud","Réduction immédiate du nombre d'incidents"], a:[0,1,2,3], e:"Six arguments au total. L'<b>adaptabilité</b> couvre le télétravail, les <b>identités externes</b> et la <b>facilitation des fusions-acquisitions</b> ; l'<b>intégration du cloud</b> passe par une gestion stricte des identités qui <b>limite le Shadow IT</b>."},
{id:"A85", ch:17, d:1, q:"Qu'est-ce que le <b>Shadow IT</b>&nbsp;?", o:["Les SI réalisés et mis en œuvre au sein d'une organisation <b>sans approbation de la DSI</b>","Les systèmes hébergés sur le darkweb","Les systèmes non inventoriés par le SOC","Les environnements de test non supervisés"], a:[0], e:"Exemples donnés : le <b>BYOD</b>, les <b>solutions <i>drive</i></b>, les <b>classeurs Excel comprenant des macros</b>. Aussi appelé <i>Rogue IT</i>."},
{id:"A86", ch:17, d:2, q:"Sur quel principe repose l'argument «&nbsp;sécurité&nbsp;» du zero trust&nbsp;?", o:["Le principe «&nbsp;<b>Assume Breach</b>&nbsp;», qui prend en compte les menaces ciblant tous les secteurs","Le principe de défense en profondeur","Le principe du chiffrement de bout en bout","Le principe de séparation des privilèges"], a:[0], e:"Tous les secteurs sont cités : <b>privés, gouvernementaux, ONG, académies</b>."},
{id:"A87", ch:17, d:3, q:"Parmi les besoins exprimés dans «&nbsp;je veux pouvoir…&nbsp;», lequel touche directement l'annuaire d'entreprise&nbsp;?", o:["Minimiser la <b>surface d'attaque de mon annuaire AD</b>","Rationaliser mes solutions de sécurité","Garantir ma conformité au RGPD","Offrir plus de flexibilité à mes utilisateurs"], a:[0], e:"La liste mélange volontairement des besoins de <b>sécurité</b>, de <b>conformité</b>, de <b>coût</b> et de <b>confort</b> — c'est ce qui permet de porter le projet devant une direction."},

/* ---- Ch. 18 : compléments ---- */
{id:"A88", ch:18, d:2, q:"Qu'est-ce qui distingue la <b>micro-segmentation</b> de la segmentation classique&nbsp;?", o:["Politiques granulaires, réseau virtuel, trafic <b>est-ouest</b>, couche <b>4</b>, SDN et conteneurisation, <b>logiciel</b>","Politiques générales, réseau physique, trafic nord-sud, couches 2 et 3, VLAN, matériel","Elle ne s'applique qu'au cloud public","Elle remplace le chiffrement des flux"], a:[0], e:"La segmentation classique, elle, est <b>matérielle</b> : réseau physique, trafic <b>nord-sud</b>, couches <b>2 et 3</b>, <b>VLAN, MPLS, pare-feu</b>, découpage <b>géographique et fonctionnel</b>."},
{id:"A89", ch:18, d:1, q:"Que désigne le trafic <b>est-ouest</b>&nbsp;?", o:["Le trafic <b>entre les appareils au sein</b> d'un centre de données","Le trafic entrant et sortant d'un centre de données","Le trafic entre deux centres de données distants","Le trafic chiffré entre continents"], a:[0], e:"Le trafic <b>nord-sud</b> est celui qui <b>entre et sort</b> d'un centre de données. La micro-segmentation vise l'est-ouest, c'est-à-dire précisément le <b>déplacement latéral</b> de l'attaquant."},
{id:"A90", ch:18, d:2, q:"Quelle est la différence entre <b>ZTA</b> et <b>ZTNA</b>&nbsp;?", o:["ZTA est l'<b>approche</b> appliquée à l'accès aux ressources ; ZTNA est la <b>technologie</b> qui sécurise l'accès réseau","ZTA est la technologie, ZTNA l'approche","ZTA concerne le cloud, ZTNA le sur site","Ce sont deux noms du même concept"], a:[0], e:"La phrase de synthèse : «&nbsp;<b>Zero Trust est le principe global, ZTA est son application à l'accès aux ressources, et ZTNA met en œuvre ces principes pour sécuriser l'accès réseau.</b>&nbsp;» Attention : le support signale qu'il ne faut pas confondre ce ZTA avec <i>Zero Trust Architecture</i>, parfois aussi abrégé ZTA."},
{id:"A91", ch:18, d:3, q:"En quoi le <b>ZTNA</b> se distingue-t-il d'un <b>VPN</b>&nbsp;?", o:["Il <b>agit au-delà du réseau</b> et <b>réduit la surface d'attaque en cachant les applications de l'Internet</b>","Il chiffre plus fortement le tunnel","Il ne nécessite pas d'authentification","Il fonctionne uniquement en interne"], a:[0], e:"Fonctionnement : il <b>bloque par défaut tous les accès</b>, n'autorise que les utilisateurs approuvés, et crée des <b>tunnels chiffrés pour chaque session d'application</b>. Le VPN, lui, place le poste <b>sur le réseau</b> — exactement le modèle périmétrique qu'on cherche à quitter."},
{id:"A92", ch:18, d:2, q:"Comment le support oppose-t-il <b>zero trust</b> (Forrester) et <b>SASE</b> (Gartner)&nbsp;?", o:["Le zero trust met l'accent sur l'<b>identité et le terminal</b> ; SASE met en avant le <b>réseau et l'infrastructure</b>","Le zero trust est cloud, SASE est sur site","Le zero trust est américain, SASE européen","Le zero trust concerne les données, SASE les applications"], a:[0], e:"SASE est «&nbsp;une vision <b>complètement cloud</b>&nbsp;», centrée sur le <b>SD-WAN</b> préféré au <b>MPLS</b> — ce qui lui vaut d'être qualifiée de «&nbsp;<b>périmétrique dans le cloud</b>&nbsp;». Le zero trust est plus <b>agnostique</b> : il prend en compte les SI sur site."},
{id:"A93", ch:18, d:2, q:"Qu'est-ce que le <b>triangle LWC</b> de la cryptographie légère&nbsp;?", o:["Le compromis entre <b>performance</b>, <b>sécurité</b> et <b>coût</b>","Le compromis entre confidentialité, intégrité et disponibilité","Les trois tailles de clé normalisées","Les trois modes de chiffrement par bloc"], a:[0], e:"Elle est conçue pour les <b>dispositifs à contraintes de ressources</b> : la <b>taille de clé</b> peut être ajustée (par exemple <b>64 bits</b>) et le <b>nombre de tours</b> réduit (par exemple <b>16 cartouches</b>). Idéale pour l'<b>IoT</b> et les <b>réseaux de capteurs sans fil</b>."},
{id:"A94", ch:18, d:2, q:"Pourquoi le zero trust met-il en avant le <b>chiffrement homomorphe</b>&nbsp;?", o:["Parce qu'il permet de <b>traiter des données chiffrées sans les déchiffrer</b>","Parce qu'il est plus rapide que le chiffrement classique","Parce qu'il ne nécessite pas de gestion de clés","Parce qu'il est imposé par le RGPD"], a:[0], e:"Quatre raisons dans le support : <b>sécurité des données</b>, <b>confidentialité</b> (même en cas de partage avec des tiers), <b>conformité</b>, et <b>réduction des risques</b> en minimisant les points d'exposition."},
{id:"A95", ch:18, d:3, q:"Quel <b>risque</b> l'IA générative introduit-elle, selon le support&nbsp;?", o:["Des risques de <b>fuite de données</b> relevant du shadow IT — que la <b>DLP</b> permet de suivre","Des risques d'injection de prompt dans les pare-feu","Des risques de saturation des journaux","Des risques de non-conformité à l'ISO 27001"], a:[0], e:"L'IA a aussi deux effets positifs sur le zero trust : elle <b>fournit des informations</b> sur les données et les événements liés aux identités, et elle <b>améliore le renseignement sur les menaces en temps réel</b> et l'<b>automatisation des réponses</b>."},

/* ---- Ch. 19 : précautions ---- */
{id:"A96", ch:19, d:2, q:"Quel travers guette une démarche zero trust <b>mal maîtrisée</b>&nbsp;?", o:["Mettre une <b>emphase excessive sur la donnée</b>, au détriment des trois autres approches","Négliger le chiffrement des flux","Multiplier les pare-feu périmétriques","Sur-investir dans la formation"], a:[0], e:"Le zero trust <b>est</b> l'approche centrée sur la donnée. Le prendre pour toute la sécurité revient à confondre un quadrant avec le tableau entier : «&nbsp;la cybersécurité est une affaire d'<b>équilibre</b> entre quatre grandes approches&nbsp;»."},
{id:"A97", ch:19, d:3, q:"Que met en garde l'<b>ANSSI</b> à propos du zero trust&nbsp;?", o:["Que faute de maturité, le déploiement peut <b>accroître la vulnérabilité</b> des SI et donner un <b>faux sentiment de sécurité</b>","Qu'il est incompatible avec le RGPD","Qu'il ne s'applique pas aux OIV","Qu'il doit être précédé d'une certification ISO 27001"], a:[0], e:"«&nbsp;Le recours à ces solutions est <b>ardu</b>, faute de maturité : le déploiement est susceptible d'entraîner des <b>erreurs d'installation ou de configuration</b>…&nbsp;»"},
{id:"A98", ch:19, d:2, q:"Sur quoi le zero trust ne dispense-t-il pas d'une réflexion autonome&nbsp;?", o:["Le chiffrement des flux","Les jetons d'authentification","La journalisation","La sensibilisation des utilisateurs","Le choix de l'éditeur de la solution"], a:[0,1,2,3], e:"Les quatre sont cités dans la conclusion. Et la phrase finale : «&nbsp;<b>tout dépend des objectifs visés et surtout du niveau de maturité déjà atteint par le SI</b>&nbsp;»."},

/* ---- Ch. 20 : TP et devoir ---- */
{id:"A99", ch:20, d:1, q:"Quelles <b>trois faiblesses</b> l'audit de la plateforme de streaming a-t-il révélées&nbsp;?", o:["Comptes utilisateurs trop privilégiés · VPN utilisé depuis des postes personnels non sécurisés · risque de compromission d'un compte administrateur","Absence de chiffrement · absence de sauvegarde · absence de journalisation","Pare-feu mal configuré · CDN non sécurisé · API exposée","Absence de MFA · absence de DLP · absence d'EDR"], a:[0], e:"Ce sont les mêmes trois faiblesses pour le <b>TP zero trust</b> et pour le <b>devoir EBIOS RM</b>."},
{id:"A100", ch:20, d:2, q:"Sur quoi serez-vous <b>réellement évalués</b> dans le devoir EBIOS RM&nbsp;?", o:["Sur la <b>cohérence de l'analyse</b> et l'<b>enchaînement des ateliers</b> — pas sur la justesse des mesures ni le réalisme du résultat","Sur la pertinence technique des mesures proposées","Sur la conformité à l'ISO 27002","Sur l'exhaustivité de l'inventaire des actifs"], a:[0], e:"L'énoncé le dit deux fois : «&nbsp;c'est sur la <b>cohérence de l'analyse</b> que vous serez évalués&nbsp;» et «&nbsp;l'objectif n'est <b>pas performatif mais pédagogique</b> […] mais sur le <b>réalisme du processus</b>&nbsp;»."},
{id:"A101", ch:20, d:2, q:"Pourquoi l'énoncé demande-t-il de «&nbsp;<b>laisser suffisamment de faiblesses</b>&nbsp;»&nbsp;?", o:["Pour <b>donner du corps à l'analyse de risques</b> : si le socle est déjà parfait, les ateliers suivants n'ont plus rien à traiter","Pour simuler une entreprise réaliste","Pour limiter le temps de travail du groupe","Pour permettre au correcteur de retrouver les erreurs"], a:[0], e:"C'est un conseil de méthode : on est <b>libre de choisir des mesures déjà en place</b>, mais un atelier 1 trop généreux vide de sens les ateliers 2 à 5."},
{id:"A102", ch:20, d:1, q:"Comment s'enchaînent les <b>cinq ateliers</b> EBIOS RM selon l'énoncé du devoir&nbsp;?", o:["Atelier 1 : le portrait robot de l'entreprise · ateliers 2, 3 et 4 : les menaces qui pèsent sur le SI · atelier 5 : le traitement du risque","Atelier 1 : les menaces · ateliers 2 à 4 : les mesures · atelier 5 : l'audit","Atelier 1 : le périmètre · ateliers 2 à 4 : les scénarios · atelier 5 : la certification","Atelier 1 : l'inventaire · ateliers 2 à 4 : les vulnérabilités · atelier 5 : le budget"], a:[0], e:"À compléter après la journée de formation avec le nom exact et les livrables de chaque atelier."},
{id:"A103", ch:20, d:2, q:"Quelles sont les contraintes formelles du devoir&nbsp;?", o:["Groupe de <b>4 à 6 personnes</b>, remise le <b>dimanche 20 septembre à 23h59</b>, format <b>PDF</b> par export d'Agile Risk Manager","Travail individuel, remise le 20 septembre, format libre","Groupe de 3, remise le 30 septembre, format PDF","Groupe de 4 à 6, remise le 20 septembre, format ODT ou DOCX"], a:[0], e:"Le devoir a été ouvert le <b>vendredi 11 septembre 2026</b>."},
{id:"A104", ch:20, d:3, q:"Dans le TP zero trust, à quel(s) principe(s) rattacher la faiblesse «&nbsp;<b>VPN depuis des postes personnels</b>&nbsp;»&nbsp;?", o:["À la <b>vérification explicite</b> — l'état de santé de l'appareil fait partie du contexte","À la <b>microsegmentation</b> — le VPN place le poste sur le réseau interne","Au moindre privilège exclusivement","À la surveillance continue exclusivement"], a:[0,1], e:"Le VPN reproduit exactement le <b>modèle périmétrique</b> qu'on cherche à quitter. La réponse structurelle est le <b>ZTNA</b>, qui «&nbsp;agit au-delà du réseau&nbsp;» et <b>cache les applications</b>. Briques associées : <b>NAC</b>, <b>MDM</b>, <b>EDR</b>, conformité du terminal."},
{id:"A105", ch:20, d:2, q:"Quel est le <b>livrable attendu</b> du TP zero trust&nbsp;?", o:["Un <b>tableau forces / faiblesses</b>, chaque problème étant associé à un ou plusieurs principes zero trust et <b>justifié</b>","Un schéma d'architecture cible","Une matrice des risques","Un plan de traitement du risque"], a:[0], e:"Les quatre principes à mobiliser dans les consignes : <b>authentification forte</b>, <b>moindre privilège</b>, <b>microsegmentation</b>, <b>surveillance continue</b>."},
{id:"A106", ch:20, d:3, q:"Quelles évaluations composent la note du module&nbsp;?", o:["QCM Moodle zero trust","QCM Moodle de la formation EBIOS RM","Analyse EBIOS sur un cas d'étude (projet de groupe)","Examen final Moodle (problème de synthèse)","Soutenance orale du projet"], a:[0,1,2,3], e:"Les quatre. Attention : la <b>journée de formation est obligatoire</b> et le <b>QCM EBIOS doit être validé à 80&nbsp;%</b> pour obtenir l'attestation de formation. Le QCM zero trust comporte <b>20 questions</b>, <b>une seule bonne réponse</b> chacune, <b>1 pt</b> par bonne réponse et <b>0</b> pour une mauvaise."}
,

/* ---- Ch. 21 : EBIOS RM, la démarche ---- */
{id:"B01", ch:21, d:1, q:"Qui publie la méthode <b>EBIOS Risk Manager</b>, et avec quel soutien&nbsp;?", o:["L'<b>ANSSI</b>, avec le soutien du <b>Club EBIOS</b>","L'ISO, avec le soutien de la CNIL","L'ENISA, avec le soutien de l'ANSSI","Le NIST, avec le soutien du Club EBIOS"], a:[0], e:"Le <b>Club EBIOS</b> est une association loi 1901 qui enrichit le référentiel français depuis <b>2003</b>. <i>EBIOS</i> est une <b>marque déposée</b> par le Secrétariat général de la défense et de la sécurité nationale."},
{id:"B02", ch:21, d:2, q:"Avec quelles normes EBIOS RM est-elle alignée&nbsp;?", o:["Conforme à <b>ISO/IEC 27005:2022</b>, compatible avec <b>ISO 31000:2018</b>","Conforme à ISO 27001, compatible avec ISO 9000","Conforme à NIS 2, compatible avec le RGPD","Conforme à l'IEC 62443"], a:[0], e:"C'est la raison d'être de la mise à jour du guide : «&nbsp;rendre la méthode <b>pleinement conforme à la norme ISO/CEI 27005:2022</b>&nbsp;»."},
{id:"B03", ch:21, d:2, q:"Quelles <b>deux approches</b> EBIOS RM combine-t-elle, et pour quels risques&nbsp;?", o:["Une approche par <b>conformité</b> pour le socle et les risques communs, y compris accidentels et environnementaux ; une approche par <b>scénarios</b> pour les risques avancés et intentionnels","Une approche quantitative et une approche qualitative","Une approche technique et une approche organisationnelle","Une approche préventive et une approche réactive"], a:[0], e:"C'est la <b>pyramide du management du risque numérique</b> : à la base, large et simple, les <b>principes de base et l'hygiène</b> ; au milieu le <b>cadre réglementaire et normatif</b> ; au sommet, avancé et ciblé, l'<b>appréciation des risques</b>."},
{id:"B04", ch:21, d:1, q:"Quels sont les <b>noms exacts</b> des cinq ateliers&nbsp;?", o:["Cadrage et socle de sécurité · Sources de risque · Scénarios stratégiques · Scénarios opérationnels · Traitement du risque","Contexte · Menaces · Vulnérabilités · Risques · Mesures","Périmètre · Actifs · Scénarios · Cotation · Plan d'action","Identifier · Protéger · Détecter · Répondre · Récupérer"], a:[0], e:"Les cinq, dans l'ordre. Les <b>ateliers 2, 3 et 4</b> constituent l'<b>appréciation des risques</b> ; l'<b>atelier 1</b> relève de l'approche par <b>conformité</b>."},
{id:"B05", ch:21, d:3, q:"Dans la chaîne logique d'EBIOS RM, <b>où</b> se cote la gravité et <b>où</b> se cote la vraisemblance&nbsp;?", o:["La <b>gravité</b> aux ateliers 1 et 3 ; la <b>vraisemblance</b> à l'atelier 4","La gravité à l'atelier 4 ; la vraisemblance à l'atelier 3","Les deux à l'atelier 5","Les deux à l'atelier 1"], a:[0], e:"C'est l'erreur la plus commune. La <b>gravité</b> est portée par le <b>scénario stratégique</b> et reste <b>identique pour tous ses chemins d'attaque</b> ; la <b>vraisemblance</b> est <b>propre à chaque scénario opérationnel</b>. Le <b>niveau de risque</b> croise les deux."},
{id:"B06", ch:21, d:2, q:"Qu'est-ce qu'un <b>scénario de risque</b>&nbsp;?", o:["L'association d'un <b>chemin d'attaque</b> et de son <b>scénario opérationnel</b>, de la source de risque jusqu'à l'objectif visé","Un scénario stratégique seul","Un scénario opérationnel seul","Un couple SR/OV"], a:[0], e:"«&nbsp;Scénario <b>complet</b>, allant de la source de risque à l'objectif visé, décrivant un chemin d'attaque et le scénario opérationnel associé.&nbsp;» C'est l'unité qu'on cote en <b>gravité × vraisemblance</b>."},
{id:"B07", ch:21, d:2, q:"Quels sont les <b>deux cycles</b> de la démarche, et que revisite chacun&nbsp;?", o:["Un <b>cycle stratégique</b> qui revisite toute l'étude et les scénarios stratégiques ; un <b>cycle opérationnel</b> qui revient sur les scénarios opérationnels","Un cycle annuel et un cycle trimestriel","Un cycle de conception et un cycle d'exploitation","Un cycle interne et un cycle écosystème"], a:[0], e:"Leurs durées sont <b>définies lors du premier atelier</b>. Le cycle opérationnel se déclenche «&nbsp;à la lumière des <b>incidents survenus</b>, de l'apparition de <b>nouvelles vulnérabilités</b> et de l'<b>évolution des modes opératoires</b>&nbsp;»."},
{id:"B08", ch:21, d:3, q:"Comment s'appelle aujourd'hui ce que l'édition 2018 nommait le <b>PACS</b>&nbsp;?", o:["Le <b>plan de traitement du risque</b>","Le plan d'assurance sécurité","Le plan de continuité","La stratégie de traitement du risque"], a:[0], e:"Trois renommages en 2024 pour rapprocher la terminologie de l'ISO : <b>PACS → plan de traitement du risque</b>, <b>entité ou personne responsable → propriétaire</b>, <b>synthèse des scénarios de risque → évaluations des risques</b>. Le sigle PACS reste employé à l'oral."},

/* ---- Ch. 22 : atelier 1 ---- */
{id:"B09", ch:22, d:1, q:"Quelles sont les <b>données de sortie</b> de l'atelier 1&nbsp;?", o:["Les éléments de cadrage ; le périmètre métier et technique (missions, valeurs métier, biens supports) ; les événements redoutés et leur gravité ; le socle de sécurité","Les couples SR/OV et leur cartographie","Les scénarios stratégiques et leur gravité","Le plan de traitement du risque"], a:[0], e:"Le socle comprend la <b>liste des référentiels applicables</b>, l'<b>état d'application</b>, et l'<b>identification et la justification des écarts</b>."},
{id:"B10", ch:22, d:2, q:"Quelle est la différence entre une <b>valeur métier</b> et un <b>bien support</b>&nbsp;?", o:["La valeur métier est <b>ce qu'on protège</b> — service, information, savoir-faire ; le bien support est le <b>composant du SI sur lequel elle repose</b>","La valeur métier est technique, le bien support est métier","La valeur métier appartient à l'écosystème, le bien support à l'organisation","Ce sont deux noms du même objet"], a:[0], e:"On cote des <b>événements redoutés</b> sur les <b>valeurs métier</b> ; on trace des <b>scénarios opérationnels</b> sur les <b>biens supports</b>. Dans EBIOS 2010, la valeur métier s'appelait <b>bien essentiel</b>."},
{id:"B11", ch:22, d:2, q:"Qui participe à l'atelier 1&nbsp;?", o:["Direction, Métiers, RSSI, DSI","RSSI et DSI uniquement","Métiers et Achats","Direction et service juridique"], a:[0], e:"Ce sont <b>les mêmes participants qu'à l'atelier 5</b> : ceux qui cadrent sont ceux qui décident du traitement. L'atelier <b>4</b>, le plus technique, ne réunit que <b>RSSI et DSI</b>."},
{id:"B12", ch:22, d:2, q:"Sur l'échelle de gravité du guide, qu'est-ce qui distingue <b>G3</b> de <b>G4</b>&nbsp;?", o:["En G4, la société <b>ne surmontera vraisemblablement pas</b> la situation — <b>sa survie est menacée</b> ; en G3 elle surmonte avec de sérieuses difficultés","En G4 il y a des impacts sur la sécurité des personnes, pas en G3","En G3 l'activité est arrêtée, en G4 elle est dégradée","G4 concerne l'écosystème, G3 l'organisation"], a:[0], e:"Deux lignes à retenir : entre <b>G2 et G3</b>, l'apparition d'<b>impacts sur la sécurité des personnes et des biens</b> ; entre <b>G3 et G4</b>, la <b>survie de l'organisation</b>. G1 = aucun impact opérationnel, simple consommation des marges."},
{id:"B13", ch:22, d:3, q:"Que dit le guide si l'évaluation du socle révèle des <b>écarts trop significatifs</b>&nbsp;?", o:["<b>Ne pas poursuivre</b> les ateliers d'appréciation des risques","Poursuivre en cotant les risques à la hausse","Passer directement à l'atelier 5","Refaire l'atelier 1 avec un périmètre élargi"], a:[0], e:"Inutile de modéliser une attaque sophistiquée si l'<b>hygiène de base</b> n'est pas en place : il faut d'abord <b>combler le socle</b>. Le guide note d'ailleurs que l'étude du socle «&nbsp;<b>occupe une grande partie</b> du processus d'analyse de risque&nbsp;»."},

/* ---- Ch. 23 : atelier 2 ---- */
{id:"B14", ch:23, d:1, q:"À quelle question l'atelier 2 répond-il&nbsp;?", o:["«&nbsp;Qui ou quoi pourrait porter atteinte aux missions et valeurs métier identifiées dans l'atelier 1, et dans quels buts&nbsp;?&nbsp;»","«&nbsp;Quelles sont les vulnérabilités de mon SI&nbsp;?&nbsp;»","«&nbsp;Quelles mesures dois-je mettre en place&nbsp;?&nbsp;»","«&nbsp;Quel est mon niveau de conformité&nbsp;?&nbsp;»"], a:[0], e:"D'où le <b>couple SR/OV</b> : la <b>source de risque</b> répond au «&nbsp;qui ou quoi&nbsp;», l'<b>objectif visé</b> au «&nbsp;dans quels buts&nbsp;»."},
{id:"B15", ch:23, d:2, q:"Sur quels <b>trois critères</b> évalue-t-on la pertinence d'un couple SR/OV&nbsp;?", o:["La <b>motivation</b>, les <b>ressources</b>, l'<b>activité</b> de la source de risque","La gravité, la vraisemblance, l'impact","La probabilité, le coût, le délai","L'exposition, la maturité, la confiance"], a:[0], e:"Les <b>ressources</b> regroupent les moyens financiers, les compétences et les infrastructures d'attaque. L'<b>activité</b> demande si la source est active dans le périmètre, l'écosystème, l'industrie concernée ou une industrie similaire."},
{id:"B16", ch:23, d:3, q:"Quel piège de vocabulaire le guide signale-t-il explicitement à l'atelier 2&nbsp;?", o:["Ne pas confondre l'<b>objectif visé</b> et la <b>motivation</b> poussant la source de risque à le réaliser","Ne pas confondre source de risque et menace","Ne pas confondre gravité et impact","Ne pas confondre partie prenante et bien support"], a:[0], e:"L'<b>objectif visé</b> est <b>ce que la source veut obtenir</b> ; la <b>motivation</b> est <b>pourquoi elle le veut</b>. Dans l'exemple du guide, «&nbsp;voler des informations en espionnant la R&amp;D&nbsp;» est l'objectif ; «&nbsp;en vue d'obtenir un avantage concurrentiel&nbsp;» est la motivation."},
{id:"B17", ch:23, d:2, q:"Combien de couples SR/OV le guide recommande-t-il de retenir&nbsp;?", o:["<b>3 à 6</b>, «&nbsp;base suffisante pour élaborer des scénarios stratégiques&nbsp;»","1 à 2","8 à 12","Autant que possible, sans limite"], a:[0], e:"Et il précise le critère de choix : privilégier des couples <b>suffisamment distincts</b> qui <b>impacteront différentes valeurs métier et biens supports</b>, avec un <b>panel différencié de profils d'attaquant</b> — et <b>sans laisser d'angle mort</b>."},

/* ---- Ch. 24 : atelier 3 ---- */
{id:"B18", ch:24, d:2, q:"Que mesure le <b>niveau de dangerosité</b> d'une partie prenante&nbsp;?", o:["La <b>capacité d'une source de risque à exploiter la relation privilégiée</b> entre cette partie prenante et l'objet de l'étude","L'intention malveillante de la partie prenante","La probabilité qu'elle soit attaquée","Son niveau de conformité réglementaire"], a:[0], e:"Le guide est explicite : le niveau de dangerosité «&nbsp;<b>ne préjuge aucunement d'une intention malveillante</b> de la part de la partie prenante&nbsp;». Un prestataire de ménage n'est pas suspect — il a un accès qu'un attaquant peut détourner."},
{id:"B19", ch:24, d:2, q:"Sur quels critères évalue-t-on les parties prenantes&nbsp;?", o:["<b>Exposition</b> = dépendance × pénétration ; <b>fiabilité cyber</b> = maturité × confiance","Gravité × vraisemblance","Motivation × ressources × activité","Impact × probabilité × détectabilité"], a:[0], e:"La dangerosité <b>croît avec l'exposition</b> et <b>décroît avec la fiabilité cyber</b>. Le guide recommande de privilégier des <b>critères objectifs et opposables</b> plutôt que des facteurs subjectifs."},
{id:"B20", ch:24, d:1, q:"Qu'est-ce qu'un <b>scénario stratégique</b>&nbsp;?", o:["Un <b>chemin d'attaque</b> allant d'une source de risque à un objectif visé, en passant par l'écosystème et les valeurs métier","Un enchaînement d'actions élémentaires sur les biens supports","Un plan de traitement à moyen terme","Une cartographie des parties prenantes"], a:[0], e:"Il est estimé en <b>GRAVITÉ</b> — et cette gravité vaut pour <b>tous</b> ses chemins d'attaque. C'est le scénario <b>opérationnel</b> (atelier 4) qui porte l'enchaînement d'actions sur les biens supports, estimé en <b>vraisemblance</b>."},
{id:"B21", ch:24, d:3, q:"Quels participants sont <b>spécifiques</b> à l'atelier 3&nbsp;?", o:["Les acteurs connaissant les <b>engagements contractuels</b> avec les parties prenantes — Achats ou Service juridique — et les <b>architectes fonctionnels</b>","La direction et les métiers","Le DSI et le RSSI","Les auditeurs internes"], a:[0], e:"C'est logique : l'atelier porte sur l'<b>écosystème</b>, et les leviers d'action y sont largement <b>contractuels</b>. Le guide cite d'ailleurs comme mesures «&nbsp;réduire la dépendance à un sous-traitant&nbsp;» ou «&nbsp;accroître la maturité cyber du…&nbsp;»."},
{id:"B22", ch:24, d:2, q:"Qu'est-ce qu'une <b>partie prenante critique (PPC)</b>&nbsp;?", o:["Une partie prenante susceptible de constituer un <b>vecteur d'attaque privilégié</b>, du fait de son accès numérique privilégié, de sa vulnérabilité ou de son exposition","Une partie prenante indispensable à l'activité","Une partie prenante soumise à NIS 2","Une partie prenante non conforme au socle"], a:[0], e:"Les parties prenantes sont les acteurs «&nbsp;dont le <b>SI est interconnecté</b> avec l'objet de l'étude&nbsp;» ou «&nbsp;pour lesquels des <b>prestations sont réalisées</b>&nbsp;» — l'infogérance par exemple."},

/* ---- Ch. 25 : atelier 4 ---- */
{id:"B23", ch:25, d:1, q:"Quelle <b>séquence d'attaque</b> le guide utilise-t-il dans son exemple de scénario opérationnel&nbsp;?", o:["<b>Connaître → Rentrer → Trouver → Exploiter</b>","Reconnaissance → Armement → Livraison → Installation","Identifier → Protéger → Détecter → Répondre","Préparer → Pénétrer → Persister → Exfiltrer"], a:[0], e:"Le guide précise que <b>plusieurs modèles existent</b> et cite la <b>cyber kill chain de Lockheed Martin</b>. Le graphe peut porter des opérateurs <b>ET</b> (les deux actions sont nécessaires) et <b>OU</b> (l'une ou l'autre suffit)."},
{id:"B24", ch:25, d:2, q:"Que confronte l'évaluation de la <b>vraisemblance</b> d'un scénario opérationnel&nbsp;?", o:["Les <b>ressources et la motivation</b> présumées de la source de risque, face au <b>socle de sécurité</b> et au <b>niveau de vulnérabilité de l'écosystème</b>","La gravité et l'impact","Le coût de l'attaque et le gain espéré","Le nombre de vulnérabilités connues"], a:[0], e:"Le niveau de vulnérabilité comprend la <b>surface d'attaque exposée</b>, les vulnérabilités <b>structurelles et organisationnelles</b>, et les <b>capacités de détection et de réaction</b>."},
{id:"B25", ch:25, d:2, q:"Sur l'échelle de vraisemblance, que signifie <b>V3</b>&nbsp;?", o:["<b>Très vraisemblable</b> : la source de risque va <b>probablement</b> atteindre son objectif","Quasi certain : elle va certainement l'atteindre","Vraisemblable : elle est susceptible de l'atteindre","Peu vraisemblable : elle a peu de chance de l'atteindre"], a:[0], e:"<b>V4</b> quasi certain (va <b>certainement</b>) · <b>V3</b> très vraisemblable (va <b>probablement</b>) · <b>V2</b> vraisemblable (est <b>susceptible</b>) · <b>V1</b> peu vraisemblable (a <b>peu de chance</b>)."},
{id:"B26", ch:25, d:3, q:"La gravité d'un scénario opérationnel, comment se détermine-t-elle&nbsp;?", o:["Elle est <b>celle du scénario stratégique associé</b>, évaluée à l'atelier 3 — on ne la réévalue pas","Elle se recalcule à partir des actions élémentaires","Elle se déduit de la vraisemblance","Elle est fixée à l'atelier 5"], a:[0], e:"Le guide le rappelle explicitement. Il suggère aussi de <b>rapprocher la vraisemblance de la pertinence du couple SR/OV</b> associé, pour vérifier la cohérence entre les deux."},
{id:"B27", ch:25, d:2, q:"Pourquoi le guide insiste-t-il sur l'<b>enchaînement</b> d'actions plutôt que sur des vulnérabilités isolées&nbsp;?", o:["Parce qu'une attaque réussie exploite <b>plusieurs failles</b>, dont chacune «&nbsp;peut sembler anodine lorsqu'on la considère individuellement&nbsp;»","Parce que les vulnérabilités isolées sont rares","Parce que les scanners ne détectent pas les vulnérabilités isolées","Parce que la norme l'impose"], a:[0], e:"La démarche doit permettre d'identifier les <b>biens supports critiques</b> susceptibles de servir de <b>vecteur d'entrée</b>, d'<b>exploitation</b> ou de <b>relais de propagation</b>."},

/* ---- Ch. 26 : atelier 5 ---- */
{id:"B28", ch:26, d:1, q:"Quelles sont les <b>quatre données de sortie</b> de l'atelier 5&nbsp;?", o:["La stratégie de traitement du risque ; la synthèse des risques résiduels ; le plan de traitement du risque ; le cadre du suivi des risques","Les scénarios de risque et leur cotation","Le socle de sécurité et ses écarts","La cartographie des sources de risque"], a:[0], e:"Les participants sont <b>les mêmes qu'à l'atelier 1</b> — Direction, Métiers, RSSI, DSI : ceux qui ont cadré décident du traitement."},
{id:"B29", ch:26, d:2, q:"Quelles sont les <b>trois classes d'acceptabilité</b> du risque&nbsp;?", o:["<b>Acceptable en l'état</b> (aucune action) · <b>tolérable sous contrôle</b> (suivi et amélioration continue) · <b>inacceptable</b> (mesures impératives à court terme)","Faible · moyen · élevé · critique","Éviter · réduire · transférer · accepter","Vert · orange · rouge"], a:[0], e:"En cas de risque <b>inacceptable</b> non traité, le guide est net : «&nbsp;<b>tout ou partie de l'activité sera refusé</b>&nbsp;». La stratégie de traitement «&nbsp;formalise les <b>seuils d'acceptation</b> et un <b>niveau de sécurité à atteindre</b> en cas de non-acceptation&nbsp;»."},
{id:"B30", ch:26, d:2, q:"Qu'est-ce qu'un <b>risque résiduel</b>&nbsp;?", o:["Le scénario de risque <b>subsistant après</b> application de la stratégie de traitement, réévalué en gravité et vraisemblance","Le risque qu'on a décidé d'ignorer","Le risque porté par l'écosystème","Le risque non identifié lors de l'appréciation"], a:[0], e:"Par opposition au <b>risque initial</b>, évalué <b>avant</b> application de la stratégie. Les deux s'évaluent sur les <b>mêmes axes</b> : gravité et vraisemblance."},
{id:"B31", ch:26, d:3, q:"Quel contrôle le guide recommande-t-il pour éviter les <b>angles morts</b> à l'atelier 5&nbsp;?", o:["Passer en revue <b>tous les événements redoutés de l'atelier 1</b> et identifier ceux qu'aucun scénario de risque n'a abordés — au besoin via une <b>matrice de couverture</b>","Recompter les biens supports","Vérifier que chaque mesure a un budget","Auditer le socle une seconde fois"], a:[0], e:"Selon leur gravité, on peut alors décider de <b>refaire une itération des ateliers 2, 3 et 4</b>. C'est exactement le type de contrôle qui démontre la <b>cohérence de l'enchaînement</b>."},
{id:"B32", ch:26, d:2, q:"Sur quoi une <b>mesure de sécurité</b> peut-elle agir, selon le guide&nbsp;?", o:["Sur une <b>valeur métier</b>, un <b>bien support</b>, ou une <b>partie prenante de l'écosystème</b>","Sur les biens supports uniquement","Sur les sources de risque","Sur les événements redoutés uniquement"], a:[0], e:"Elle peut être <b>fonctionnelle, technique ou organisationnelle</b>, et prendre «&nbsp;la forme de <b>solutions ou d'exigences pouvant être inscrites dans un contrat</b>&nbsp;». Certaines se <b>renforcent mutuellement</b> selon quatre axes : <b>gouvernance, protection, défense, résilience</b>."},
{id:"B33", ch:26, d:3, q:"Qu'est-ce que l'<b>homologation de sécurité</b>&nbsp;?", o:["La validation, par une <b>autorité d'homologation</b>, que le niveau de sécurité atteint est conforme aux attentes et que les <b>risques résiduels sont acceptés</b>","La certification d'un produit par un organisme accrédité","L'obtention d'une attestation ISO 27001","L'accord de l'ANSSI sur une architecture"], a:[0], e:"C'est l'un des trois usages annoncés d'EBIOS RM. Le repère : on <b>certifie un produit</b>, on <b>homologue un système</b>."},

/* ---- Ch. 27 : adapter et conduire ---- */
{id:"B34", ch:27, d:2, q:"Pour évaluer le <b>niveau de menace de l'écosystème</b> seul, quel atelier suffit&nbsp;?", o:["L'<b>atelier 3</b>, étape (A) uniquement — sans avoir conduit les ateliers 1 et 2","L'atelier 1","Les ateliers 1, 2 et 3","Les cinq ateliers"], a:[0], e:"EBIOS RM est «&nbsp;une véritable <b>boîte à outils</b>&nbsp;» dont on adapte le niveau de détail et le séquencement. Pour <b>orienter un audit ou un test d'intrusion</b>, ce sont les ateliers <b>3 et 4</b> ; pour une <b>étude complète en vue d'une homologation</b>, les <b>cinq</b>."},
{id:"B35", ch:27, d:2, q:"Dans le devoir, où faut-il faire apparaître les <b>trois faiblesses</b> révélées par l'audit&nbsp;?", o:["Dans l'<b>atelier 1</b>, comme <b>écarts au socle de sécurité</b> — identifiés et justifiés","Dans l'atelier 2, comme sources de risque","Dans l'atelier 5, comme mesures à prendre","Nulle part : il faut les corriger avant de commencer"], a:[0], e:"L'énoncé demande de «&nbsp;<b>laisser suffisamment de faiblesses</b> pour donner du corps à l'analyse&nbsp;». Un socle déclaré parfait vide de sens les ateliers 2 à 5. Ces faiblesses redeviendront des <b>actions élémentaires</b> dans les graphes de l'atelier 4."},
{id:"B36", ch:27, d:3, q:"Quels points de contrôle démontrent la <b>cohérence de l'enchaînement</b> dans le devoir&nbsp;?", o:["Chaque valeur métier porte un événement redouté","Chaque couple SR/OV donne au moins un scénario stratégique","Chaque partie prenante critique apparaît dans un chemin d'attaque","Chaque risque inacceptable a des mesures et un risque résiduel réévalué","Chaque mesure a un coût chiffré et un fournisseur identifié"], a:[0,1,2,3], e:"Le chiffrage n'est pas demandé — l'énoncé précise que l'évaluation ne porte <b>pas sur la justesse des mesures</b>. Ajoute le contrôle transversal : la <b>gravité</b> n'apparaît qu'aux ateliers 1 et 3, la <b>vraisemblance</b> qu'à l'atelier 4."}
];
